import { HTTPController, HTTPMethod, HTTPMethodEnum, HTTPParam } from 'egg';

@HTTPController({ path: '/api' })
export class ApiController {
  @HTTPMethod({ method: HTTPMethodEnum.GET, path: '/:name' })
  async getByName(@HTTPParam() name: string) {
    return { name };
  }

  @HTTPMethod({ method: HTTPMethodEnum.GET, path: '/health' })
  async health() {
    return { status: 'ok' };
  }
}

import { HTTPController, HTTPMethod, HTTPMethodEnum } from 'egg';

@HTTPController({ path: '/api/users' })
export class UserController {
  @HTTPMethod({ method: HTTPMethodEnum.GET, path: '/' })
  async list() {
    return { users: [] };
  }
}

import { SingletonProto, AccessLevel } from 'egg';

@SingletonProto({ accessLevel: AccessLevel.PUBLIC })
export class ProductService {
  async findById(id: string) {
    return { id, name: 'Product ' + id, price: 99 };
  }

  async create(data: { name: string; price: number }) {
    return { id: 'new-id', ...data };
  }
}

import { MCPController, MCPTool, MCPToolResponse, ToolArgs, ToolArgsSchema, Inject } from '@eggjs/tegg';
import { z } from '@eggjs/tegg/zod';

const SearchSchema = z.object({
  keyword: z.string({ description: 'search keyword' }),
  limit: z.number().optional(),
});

@MCPController()
export class DocMCPController {
  @MCPTool({ description: 'Search internal docs' })
  async search(
    @ToolArgsSchema(SearchSchema) args: ToolArgs<typeof SearchSchema>,
  ): Promise<MCPToolResponse> {
    return { content: [{ type: 'text', text: 'results' }] };
  }
}

import { Inject, Logger } from 'egg';
import { IntervalParams, Schedule, ScheduleType } from 'egg/schedule';

@Schedule<IntervalParams>({
  type: ScheduleType.WORKER,
  scheduleData: { interval: '1h' },
})
export class CleanTask {
  @Inject()
  private logger: Logger;

  async subscribe() {
    this.logger.info('cleaning...');
  }
}

import { SingletonProto, AccessLevel } from 'egg';

@SingletonProto({ accessLevel: AccessLevel.PUBLIC })
export class CacheService {
  private cache = new Map<string, any>();

  async refresh() {
    this.cache.clear();
    // reload from db
  }

  get(key: string) {
    return this.cache.get(key);
  }
}

import { Controller } from 'egg';

export default class UserController extends Controller {
  async show() {
    const { ctx } = this;
    const id = ctx.params.id;
    const user = await ctx.service.user.find(id);
    ctx.body = { success: true, data: user };
  }

  async create() {
    const { ctx } = this;
    const body = ctx.request.body;
    const user = await ctx.service.user.create(body);
    ctx.status = 201;
    ctx.body = { success: true, data: user };
  }
}
